function updateViewerState(){
  updateViewerLayout();const dirty=imageEditors.filter(editor=>editor.dirty()).length;$('viewer-dirty').textContent=dirty?dirty+' 张未保存':'';$('viewer-save-all').hidden=previewRows.length<2||!dirty;$('viewer-save-all').disabled=savingAll;
  const state=activeImageEditor?.getState();if(!state)return;
  $('viewer-current').textContent='当前图：'+(activeImageEditor.element.closest('.viewer-panel')?.dataset.title||'');
  $('viewer-zoom').textContent=Number((state.scale*100).toFixed(1))+'%';
  for(const [name,b] of viewerButtons){
    b.disabled=!state.ready||name==='undo'&&!state.canUndo||name==='redo'&&!state.canRedo||name==='clear'&&!state.hasAnnotations||name==='save'&&(!state.dirty||state.saving);
    if(['pan','zoom','ruler'].includes(name))b.setAttribute('aria-pressed',String(state.tool===name));
    if(name==='axes'||name==='show')b.setAttribute('aria-pressed',String(name==='axes'?state.showAxes:state.show));
    if(name==='expand')b.setAttribute('aria-expanded',String(state.expanded));
    if(name==='save')b.hidden=!state.dirty&&!state.saving;
    if(['clear','undo','redo'].includes(name))b.hidden=!state.hasAnnotations&&!state.canUndo&&!state.canRedo;
  }
  for(const editor of imageEditors){const label=editor.element.closest('.viewer-panel')?.querySelector('.panel-zoom');if(label)label.textContent=Number((editor.getState().scale*100).toFixed(1))+'%';}
}
