  const scope=comparisonReturn.length?comparisonReturn:filterRows(),index=scope.findIndex(item=>item.id===rows[0].id);$('viewer-counter').textContent=rows.length===1&&index>=0?(index+1)+' / '+scope.length:'';options($('viewer-layout'),[['auto','自动布局'],...(rows.length>2?[['2','两列']]:[]),[String(rows.length),'一行']],layout);$('viewer-layout').hidden=rows.length<2;
