function compareSelected(){const rows=[...selected].map(image);if(rows.length<2||rows.length>4||rows.some(r=>!core.isImage(r)))return toast('请选择 2–4 张图片');openViewer(rows)}
function neighbor(direction){if(previewRows.length!==1)return;const rows=comparisonReturn.length?comparisonReturn:filterRows(),index=rows.findIndex(r=>r.id===previewRows[0].id);if(rows[index+direction])openViewer([rows[index+direction]],comparisonReturn,comparisonReturnLayout)}
function openExport(lid='',fid=''){options($('export-library'),[['','全部图库'],...db.libraries.map(l=>[l.id,l.name])],lid);options($('export-folder'),[['','全部文件夹'],...db.folders.map(f=>[f.id,f.path])],fid);$('export-hidden').checked=false;$('export-result').replaceChildren();exportCount();$('export-dialog').showModal()}
function exportCount(){const lid=$('export-library').value,fid=$('export-folder').value,scope=fid?core.descendants(db.folders,fid):null;const count=db.images.filter(r=>(!lid||r.library_id===lid)&&(!scope||[...r.folders,...r.smart_folders||[]].some(f=>scope.has(f)))&&($('export-hidden').checked||!r.hidden)).length;$('export-count').textContent=`${count} 份素材 · 独立只读快照`}
function importOptionsFromUI(){return {folder_id:$('import-folder').value||null,tags:tags($('import-tags').value),hierarchy:$('import-hierarchy').checked,auto_export:$('import-export').checked}}
function fillImportPreset(lid,fid){const l=lib(lid),o=l?.import_options||{};$('import-name-row').hidden=!!lid;$('import-name').value=l?.name||'';options($('import-folder'),[['','不指定'],...manualOptions()],fid||o.folder_id||'');$('import-tags').value=(o.tags||[]).join(', ');$('import-hierarchy').checked=!!o.hierarchy;$('import-export').checked=o.auto_export!==false;$('import-run').textContent=lid&&!uploadFiles.length?'保存规则':'导入'}
function openImport(lid='',fid=''){options($('import-target'),[['','新建图库'],...db.libraries.map(l=>[l.id,l.name])],lid);uploadFiles=[];fillImportPreset(lid,fid);$('file-summary').textContent='尚未选择';$('import-progress').textContent='';$('file-picker').value='';$('directory-picker').value='';$('replace-upload').checked=false;if(!$('import-dialog').open)$('import-dialog').showModal()}
function selectFiles(files){uploadFiles=files;$('file-summary').textContent=`${files.length} 个文件 · ${bytes(files.reduce((s,x)=>s+x.file.size,0))}`;$('import-run').textContent='导入';if(!$('import-name').value&&files.length)$('import-name').value='新图库'}
const readFile=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('无法读取 '+file.name));r.readAsDataURL(file)});
const uploadPath=file=>file.webkitRelativePath?file.webkitRelativePath.split('/').slice(1).join('/'):file.name;
function importMessage(r){return `新增 ${r.added} · 更新 ${r.changed} · 跳过 ${r.skipped.length}`+(r.export_error?'；导出未完成：'+r.export_error:r.export?' · 离线 HTML 已生成':'')}
async function doImport(){let session;try{const lid=$('import-target').value;if(!uploadFiles.length&&lid){await mutate('import-options',{library_id:lid,options:importOptionsFromUI()});$('import-dialog').close();toast('导入规则已保存');return}if(!uploadFiles.length)throw Error('请选择文件或文件夹');if(uploadFiles.some(x=>x.file.size>20*1048576))throw Error('单文件超过 20 MiB，请使用命令行导入');if(uploadFiles.reduce((s,x)=>s+x.file.size,0)>256*1048576)throw Error('单次最多 256 MiB，请分批导入');busyImport=true;$('import-run').disabled=$('import-cancel').disabled=true;session=(await api('import/begin',{name:$('import-name').value,library_id:lid||null,replace:$('replace-upload').checked,options:importOptionsFromUI()})).id;for(let i=0;i<uploadFiles.length;i++){const file=uploadFiles[i];$('import-progress').textContent=`${i+1} / ${uploadFiles.length} · ${file.path}`;await api('import/add',{id:session,files:[{path:file.path,data:await readFile(file.file)}]})}$('import-progress').textContent='保存素材与归类规则…';const r=await api('import/commit',{id:session});session=null;await load();$('import-dialog').close();go('library',r.library_id);toast(importMessage(r))}catch(error){toast(error.message,true);$('import-progress').textContent='未完成：'+error.message;if(session)await api('import/cancel',{id:session}).catch(()=>{})}finally{busyImport=false;$('import-run').disabled=$('import-cancel').disabled=false}}
function entryFile(entry){return new Promise((resolve,reject)=>entry.file(resolve,reject))}
function readEntries(reader){return new Promise((resolve,reject)=>reader.readEntries(resolve,reject))}
async function walkDropped(entry,prefix='',skipRoot=false){if(entry.isFile)return [{file:await entryFile(entry),path:prefix+entry.name}];if(!entry.isDirectory)return [];const reader=entry.createReader(),result=[],childPrefix=skipRoot?prefix:prefix+entry.name+'/';for(;;){const batch=await readEntries(reader);if(!batch.length)break;for(const child of batch)result.push(...await walkDropped(child,childPrefix));if(result.length>5000)throw Error('单次最多导入 5000 个文件')}return result}
let dragDepth=0;
async function droppedFiles(dt){const entries=[...dt.items||[]].map(i=>i.webkitGetAsEntry?.()).filter(Boolean),files=[];if(entries.length){for(const e of entries)files.push(...await walkDropped(e,'',entries.length===1&&e.isDirectory))}else{for(const file of dt.files)files.push({file,path:file.name})}return files}

function noteIdentity(){return noteTarget.image?{kind:'image',id:noteTarget.image.id}:{kind:'group',id:noteTarget.group.library_id+'::'+noteTarget.group.name}}
function openNote(target){noteTarget=target;$('note-title').textContent=target.image?target.image.title:target.group.name;$('note-text').value=(target.image||target.group).note||'';$('attachment-progress').textContent='';$('attachment-picker').value='';renderAttachments();$('note-dialog').showModal()}
function renderAttachments(){const target=noteIdentity(),n=$('attachment-list');n.replaceChildren();for(const a of db.attachments.filter(a=>a.kind===target.kind&&a.target_id===target.id)){const row=el('div',undefined,'attachment-row');row.append(link(a.filename,a.url,a.filename),button('Finder',()=>api('attachment/reveal',{id:a.id})),button('移除',()=>openDelete([{kind:'attachment',id:a.id,name:a.filename}])));row.oncontextmenu=e=>menu([['下载',()=>link(a.filename,a.url,a.filename).click()],['在 Finder 中显示',()=>api('attachment/reveal',{id:a.id})],['永久删除…',()=>openPurge('attachment',a.id,a.filename),'danger']],e);n.append(row)}}
async function attachFiles(files){if(busyNote)return;busyNote=true;const target=noteIdentity();try{for(let i=0;i<files.length;i++){const file=files[i];let session;try{session=(await api('attachment/begin',{kind:target.kind,target_id:target.id,filename:file.name,size:file.size})).id;let sequence=0;for(let offset=0;offset<file.size;offset+=4*1024**2){$('attachment-progress').textContent=`${i+1}/${files.length} · ${file.name} · ${Math.round(offset/file.size*100)}%`;await api('attachment/chunk',{id:session,sequence:sequence++,data:await readFile(file.slice(offset,offset+4*1024**2))})}await api('attachment/finish',{id:session});session=null}catch(e){if(session)await api('attachment/cancel',{id:session}).catch(()=>{});throw e}}await load();renderAttachments();$('attachment-progress').textContent='附件已保存'}catch(e){toast(e.message,true);$('attachment-progress').textContent=e.message}finally{busyNote=false}}

