document.addEventListener('keydown',e=>{const editing=e.target.closest('input,textarea,select,[contenteditable="true"]');const modal=document.querySelector('dialog[open]:not(#viewer)')||($('viewer').open?$('viewer'):null);if((e.metaKey||e.ctrlKey)&&['k','f'].includes(e.key.toLowerCase())&&!modal){e.preventDefault();$('global-search').focus();$('global-search').select();return}if(! $('context-menu').hidden){if(e.key==='Escape')closeMenu();if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const items=[...$('context-menu').querySelectorAll('button:not(:disabled)')],at=items.indexOf(document.activeElement);items[(at+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}return}if(editing)return;if(modal){if(modal.id==='viewer'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();neighbor(e.key==='ArrowLeft'?-1:1)}return}if((e.metaKey||e.ctrlKey)&&e.key==='a'&&$('image-grid')){e.preventDefault();selected=new Set(filterRows().map(r=>r.id));renderGrid();renderInspector()}else if(e.key===' '&&selected.size){e.preventDefault();openViewer([...selected].slice(0,4).map(image))}else if(e.key==='Enter'&&(e.metaKey||e.ctrlKey))compareSelected();else if(e.key==='Backspace'&&(e.metaKey||e.ctrlKey)&&selected.size){e.preventDefault();openDelete([...selected].map(id=>({kind:'image',id,name:image(id).title})))}else if(e.key==='Escape'){selected.clear();inspected='';renderGrid();renderInspector()}});
